PARITY = Path(__file__).resolve().parent / "parity"
GENERATOR = (
    "cd apps/api && UPDATE_ENGINE_FIXTURE=1 .venv/bin/python manage.py test"
    " forkluck.test_mac_parity_fixtures"
)


def _decimal(value: Any) -> Decimal | None:
    return None if value is None else Decimal(str(value))


def _plain(value: Any) -> Any:
    """JSON values only: Decimals as floats, tuples as lists."""
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {str(key): _plain(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    return value


def pin(test: SimpleTestCase, name: str, cases: dict[str, Any]) -> None:
    """Write the fixture when asked to or when it is missing, then compare."""
    generated = json.loads(
        json.dumps({"generator": GENERATOR, **_plain(cases)}, allow_nan=False)
    )
    path = PARITY / name
    if os.environ.get("UPDATE_ENGINE_FIXTURE") or not path.exists():
        path.write_text(
            json.dumps(generated, indent=2, ensure_ascii=False, allow_nan=False) + "\n",
            encoding="utf-8",
        )
    test.assertEqual(json.loads(path.read_text(encoding="utf-8")), generated)


def _scenario(name: str) -> dict[str, Any]:
    return json.loads((PARITY / "scenarios" / name).read_text(encoding="utf-8"))


class Library:
    """A scenario document built into real rows for one user.

    Efficiency is stored as 100 where the scenario says 0, because the
    database refuses 0; `efficiency_overrides` carries the written value so
    the costing read can see it as the Mac editor would hold it.
    """

    def __init__(self, user: User, document: dict[str, Any]):
        self.user = user
        self.document = document
        self.ids: dict[str, str] = {}
        self.catalog: dict[str, CatalogIngredient] = {}
        self.ingredients: dict[str, Ingredient] = {}
        self.recipes: dict[str, Recipe] = {}
        self.items: dict[str, RecipeItem] = {}
        self.efficiency_overrides: dict[str, Decimal] = {}
        settings = document["settings"]
        BenchCostSettings.objects.update_or_create(
            user=user,
            defaults={
                "wage_per_hour_cents": settings["wagePerHourCents"],
                "food_cost_target_bps": settings["foodCostTargetBps"],
            },
        )
        for entry in document["catalog"]:
            self._catalog(entry)
        for entry in document["ingredients"]:
            self._ingredient(entry)
        for entry in document["recipes"]:
            self._recipe(entry)
        for entry in document["recipes"]:
            self._lines(entry)
        catalog_measure_sources.cache_clear()

    def _catalog(self, entry: dict[str, Any]) -> None:
        row = CatalogIngredient.objects.create(key=entry["key"], name=entry["name"])
        self.catalog[entry["key"]] = row
        for synonym in entry["synonyms"]:
            CatalogIngredientAlias.objects.create(
                ingredient=row,
                text=synonym,
                normalized_text=normalized_name(synonym),
                provenance="catalog",
            )
        for keys, status in ((entry["allergens"], "contains"), (entry["verify"], "checkLabel")):
            for key in keys:
                CatalogIngredientAllergen.objects.create(
                    ingredient=row,
                    allergen=key,
                    status=status,
                    source_kind="catalog",
                    source_ref=entry["key"],
                )
        for measure in entry["measures"]:
            CatalogIngredientMeasure.objects.create(
                ingredient=row,
                unit=measure["unit"],
                amount=_decimal(measure["amount"]),
                grams=_decimal(measure["grams"]),
                qualifier=measure["qualifier"],
                source_kind="catalog",
                source_ref=entry["key"],
                confidence=measure["confidence"],
                is_default=True,
            )

    def _ingredient(self, entry: dict[str, Any]) -> None:
        catalog = self.catalog.get(entry["catalogKey"]) if entry["catalogKey"] else None
        row = Ingredient.objects.create(
            user=self.user,
            name=entry["name"],
            status=entry["status"],
            non_edible=entry["nonEdible"],
            purchase_cost_cents=entry["purchaseCostCents"],
            purchase_size=_decimal(entry["purchaseSize"]),
            purchase_unit=entry["purchaseUnit"],
            yield_percent=_decimal(entry["yieldPercent"]),
            catalog_ingredient=catalog,
            nutrition_per_100g=entry["nutritionPer100g"],
            sugars_are_added=entry["sugarsAreAdded"],
            nutrition_label_name=entry["nutritionLabelName"],
        )
        self.ingredients[entry["key"]] = row
        self.ids[str(row.id)] = entry["key"]
        self.ids[row.public_id] = entry["key"]
        conversion = entry["conversion"]
        if conversion is not None:
            IngredientConversion.objects.create(
                user=self.user,
                ingredient=row,
                average_weight=conversion["usesStandard"],
                weight_amount=_decimal(conversion["weightAmount"]),
                weight_unit=conversion["weightUnit"],
                volume_amount=_decimal(conversion["volumeAmount"]),
                volume_unit=conversion["volumeUnit"],
                each_amount=_decimal(conversion["eachAmount"]),
                each_unit=conversion["eachUnit"],
                source=conversion["source"],
                confidence=conversion["confidence"],
            )
        for measure in entry["measures"]:
            IngredientMeasure.objects.create(
                ingredient=row,
                unit=measure["unit"],
                amount=_decimal(measure["amount"]),
                grams=_decimal(measure["grams"]),
                qualifier=normalized_name(measure["qualifier"]),
            )
        for preparation in entry["preparations"]:
            Preparation.objects.create(
                user=self.user,
                ingredient=row,
                name=preparation["name"],
                normalized_name=normalized_name(preparation["name"]),
                yield_percent=_decimal(preparation["yieldPercent"]),
                source=preparation["source"],
                average_weight=preparation["usesStandard"],
                weight_amount=_decimal(preparation["weightAmount"]),
                weight_unit=preparation["weightUnit"],
                volume_amount=_decimal(preparation["volumeAmount"]),
                volume_unit=preparation["volumeUnit"],
                each_amount=_decimal(preparation["eachAmount"]),
                each_unit=preparation["eachUnit"],
            )
        for allergen, status in entry["allergenOverrides"].items():
            IngredientAllergenOverride.objects.create(
                ingredient=row, allergen=allergen, status=status
            )

    def _recipe(self, entry: dict[str, Any]) -> None:
        row = Recipe.objects.create(
            user=self.user,
            title=entry["title"],
            kind=entry["kind"],
            status=entry["status"],
            yield_amount=entry["yieldAmount"],
            yield_unit=entry["yieldUnit"],
            serving_amount=_decimal(entry["servingAmount"]),
            serving_unit=entry["servingUnit"],
            menu_price_cents=entry["menuPriceCents"],
            nutrition_serving_amount=_decimal(entry["nutritionServingAmount"]),
            nutrition_serving_unit=entry["nutritionServingUnit"],
            nutrition_package_amount=_decimal(entry["nutritionPackageAmount"]),
            nutrition_package_unit=entry["nutritionPackageUnit"],
            prep_time_amount=_decimal(entry["prepTimeAmount"]),
            prep_time_unit=entry["prepTimeUnit"],
            auto_prep_time_enabled=entry["autoPrepTimeEnabled"],
        )
        self.recipes[entry["key"]] = row
        self.ids[str(row.id)] = entry["key"]
        self.ids[row.public_id] = entry["key"]
        equivalency = entry["equivalency"]
        if equivalency is not None:
            RecipeEquivalency.objects.create(
                recipe=row,
                mass_amount=_decimal(equivalency["massAmount"]),
                mass_unit=equivalency["massUnit"],
                volume_amount=_decimal(equivalency["volumeAmount"]),
                volume_unit=equivalency["volumeUnit"],
                count_amount=_decimal(equivalency["countAmount"]),
                count_unit=equivalency["countUnit"],
                standard=equivalency["standard"],
            )
        for position, step in enumerate(entry["steps"]):
            step_row = RecipeStep.objects.create(
                recipe=row,
                position=position,
                kind=step["kind"],
                title=step["title"],
                body=step["body"],
                labor_kind=step["laborKind"],
            )
            for timing in step["timings"]:
                RecipeTiming.objects.create(
                    step=step_row,
                    seconds=timing["seconds"],
                    yield_count=timing["yieldCount"],
                )

    def _lines(self, entry: dict[str, Any]) -> None:
        recipe = self.recipes[entry["key"]]
        for position, line in enumerate(entry["lines"]):
            efficiency = _decimal(line["efficiency"])
            item = RecipeItem.objects.create(
                recipe=recipe,
                position=position,
                kind=line["kind"],
                display_name=line["displayName"],
                quantity=_decimal(line["quantity"]),
                unit=line["unit"],
                preparation_note=line["preparationNote"],
                efficiency=efficiency if efficiency else Decimal(100),
                efficiency_after_cooking=_decimal(line["efficiencyAfterCooking"]),
                is_base=line["isBase"],
                excluded_from_cost=line["excludedFromCost"],
                ingredient=self.ingredients.get(line["ingredientKey"] or ""),
                subrecipe=self.recipes.get(line["subrecipeKey"] or ""),
            )
            if not efficiency:
                self.efficiency_overrides[str(item.id)] = efficiency
            self.items[line["key"]] = item
            self.ids[str(item.id)] = line["key"]

    def keyed(self, value: Any) -> Any:
        """The payload with every database id written as its scenario key."""
        if isinstance(value, dict):
            return {self.ids.get(key, key): self.keyed(item) for key, item in value.items()}
        if isinstance(value, list):
            return [self.keyed(item) for item in value]
        if isinstance(value, str):
            return self.ids.get(value, value)
        return value


def _purchase_issues(
    model: RecipeHealthReadModel, ingredient_id: str, quantity: float, unit: str, note: str
) -> list[str] | None:
    """The purchase_quantity issue codes behind one costing line, as
    `_sale_units_for` reaches them, so the "needs conversion" state is pinned."""
    match = model.by_id.get(ingredient_id)
    if match is None or match.is_component:
        return None
    preparation = _preparation_for(match, note)
    expansion = purchase_quantity(
        quantity,
        unit,
        PurchaseBasis(
            purchase_size=match.purchase_size,
            purchase_unit=match.purchase_unit,
            yield_percent=match.yield_percent,
            conversion=tuple(Measure(amount, pair) for amount, pair in match.conversion),
            conversion_is_automatic=match.conversion_is_automatic,
        ),
        PreparationBasis(
            yield_percent=preparation.yield_percent,
            conversion=tuple(
                Measure(amount, pair) for amount, pair in preparation.conversion
            ),
            conversion_is_automatic=preparation.conversion_is_automatic,
        )
        if preparation is not None
        else None,
        standard_bridge=lambda source, target: _standard_volume_ratio(
            source, target, match, "" if preparation is not None else note
        ),
    )
    return [issue.code for issue in expansion.issues]


class CostingParityFixtureTests(TestCase):
    """`costing-cases.json`: what the recipe list and Cost tab read, per recipe."""

    def test_costing_cases(self):
        user = User.objects.create_user(
            email="mac-costing@example.test", password="a-long-test-passphrase-2468"
        )
        scenario = _scenario("costing.json")
        library = Library(user, scenario)
        model = RecipeHealthReadModel(user)
        graph = model._owner_recipes()
        for recipe in graph.values():
            for item in recipe._normalized_items:
                override = library.efficiency_overrides.get(str(item.id))
                if override is not None:
                    item.efficiency = override

        expect: dict[str, Any] = {}
        for entry in scenario["recipes"]:
            recipe = graph[str(library.recipes[entry["key"]].id)]
            total, _issues, _declared = model._normalized_cost(recipe)
            row = model._normalized_row(recipe)
            seconds, untimed = labor_seconds_per_batch(recipe, recipe.steps.all())
            probes: dict[str, Any] = {}
            for line in entry["lines"]:
                item = library.items[line["key"]]
                if item.ingredient_id is None or item.quantity is None or not item.unit:
                    continue
                ingredient_id = str(item.ingredient_id)
                quantity = float(item.quantity)
                probes[line["key"]] = {
                    "ingredientCents": model.ingredient_cents(
                        ingredient_id, quantity, item.unit, item.preparation_note
                    ),
                    "lineGrams": model.line_grams(
                        ingredient_id,
                        quantity,
                        item.unit,
                        normalized_name(item.preparation_note),
                    ),
                    "purchaseIssues": _purchase_issues(
                        model, ingredient_id, quantity, item.unit, item.preparation_note
                    ),
                }
            expect[entry["key"]] = {
                "lineCosts": library.keyed(model.normalized_item_costs(recipe)),
                "total": total,
                "portionCents": row["ingredientCents"],
                "suffix": row["suffix"],
                "menuPriceCents": row["menuPriceCents"],
                "foodCost": row["foodCost"],
                "overTarget": row["overTarget"],
                "issues": row["issues"],
                "laborSeconds": seconds,
                "untimedSteps": untimed,
                "labor": row["labor"],
                "probes": probes,
            }
        pin(self, "costing-cases.json", {"scenario": scenario, "expect": expect})


