def _purchase_basis(value: dict[str, Any]) -> PurchaseBasis:
    return PurchaseBasis(
        purchase_size=value["purchaseSize"],
        purchase_unit=value["purchaseUnit"],
        yield_percent=value["yieldPercent"],
        conversion=tuple(Measure(pair["amount"], pair["unit"]) for pair in value["conversion"]),
        conversion_is_automatic=value["conversionIsAutomatic"],
    )


def _source(size, unit, *, yield_percent=None, pairs=(), automatic=True):
    return {
        "purchaseSize": size,
        "purchaseUnit": unit,
        "yieldPercent": yield_percent,
        "conversion": [{"amount": amount, "unit": pair} for amount, pair in pairs],
        "conversionIsAutomatic": automatic,
    }


def _prep(yield_percent=None, pairs=(), automatic=True):
    return {
        "yieldPercent": yield_percent,
        "conversion": [{"amount": amount, "unit": pair} for amount, pair in pairs],
        "conversionIsAutomatic": automatic,
    }


