def _bridge(value: dict[str, Any] | None):
    if value is None:
        return None
    match = PriceSource(
        id="bridge",
        normalized_name=normalized_name(value["name"]),
        measure_name=normalized_name(value["name"]),
        purchase_cost_cents=1,
    )
    return lambda source, target: _standard_volume_ratio(
        source, target, match, value["qualifier"]
    )


def _quantity(value) -> dict[str, Any] | None:
    return None if value is None else {"amount": value.amount, "unit": value.unit}


def _equivalency(value: dict[str, Any] | None) -> EquivalencyBasis | None:
    if value is None:
        return None
    return EquivalencyBasis(
        mass=Measure(*value["mass"]) if value["mass"] else None,
        volume=Measure(*value["volume"]) if value["volume"] else None,
        count=Measure(*value["count"]) if value["count"] else None,
        standard=value["standard"],
    )


def _hint_row(value: dict[str, Any]) -> SimpleNamespace:
    """An ingredient as ingredient_allergen_hints reads it, without a database."""
    catalog = (
        SimpleNamespace(
            allergen_defaults=SimpleNamespace(
                all=lambda: [
                    SimpleNamespace(allergen=key, status=status)
                    for key, status in value["catalog"].items()
                ]
            )
        )
        if value["catalog"] is not None
        else None
    )
    return SimpleNamespace(
        non_edible=value["nonEdible"],
        catalog_ingredient_id="catalog" if catalog is not None else None,
        catalog_ingredient=catalog,
        catalog_product_id=None,
        allergen_overrides=SimpleNamespace(
            all=lambda: [
                SimpleNamespace(allergen=key, status=status)
                for key, status in value["overrides"].items()
            ]
        ),
        nutrition_package_ingredients=value["package"],
    )


def _or_error(function, *args):
    try:
        return function(*args)
    except food_data.FoodDataError as error:
        return {"error": str(error)}


class ModelFreeParityFixtureTests(SimpleTestCase):
    """The fixtures that need no database."""

    def test_purchase_quantity_cases(self):
        cases = []
        for case in PURCHASES:
            expansion = purchase_quantity(
                case["amount"],
                case["unit"],
                _purchase_basis(case["source"]),
                PreparationBasis(
                    yield_percent=case["preparation"]["yieldPercent"],
                    conversion=tuple(
                        Measure(pair["amount"], pair["unit"])
                        for pair in case["preparation"]["conversion"]
                    ),
                    conversion_is_automatic=case["preparation"]["conversionIsAutomatic"],
                )
                if case["preparation"] is not None
                else None,
                standard_bridge=_bridge(case["bridge"]),
            )
            cases.append(
                {
                    **case,
                    "expect": {
                        "usage": _quantity(expansion.usage),
                        "purchase": _quantity(expansion.purchase),
                        "purchaseUnits": expansion.purchase_units,
                        "issues": [issue.code for issue in expansion.issues],
                    },
                }
            )
        batches = []
        for case in MEASURE_PAIRS:
            equivalency = _equivalency(case["equivalency"])
            batch = recipe_batch_basis(case["yieldAmount"], case["yieldUnit"], equivalency)
            batches.append(
                {
                    **case,
                    "expect": {
                        "pairs": [
                            {"amount": amount, "unit": unit}
                            for amount, unit in recipe_measure_pairs(
                                case["yieldAmount"], case["yieldUnit"], equivalency
                            )
                        ],
                        "grams": batch.grams,
                        "pieces": _quantity(batch.pieces),
                        "volume": _quantity(batch.volume),
                        "issues": [issue.code for issue in batch.issues],
                        "shares": [
                            {
                                "amount": amount,
                                "unit": unit,
                                "factor": share.factor,
                                "grams": share.grams,
                                "issues": [issue.code for issue in share.issues],
                            }
                            for amount, unit in SHARES
                            for share in [share_of_batch(amount, unit, batch)]
                        ],
                    },
                }
            )
        pin(
            self,
            "purchase-quantity-cases.json",
            {
                "purchaseQuantity": cases,
                "batches": batches,
                "normalizedName": [
                    {"input": name, "expect": normalized_name(name)} for name in NAMES
                ],
                "qualifierClauses": [
                    {"input": text, "expect": list(qualifier_clauses(text))} for text in CLAUSES
                ],
                "density": [
                    {
                        "milliliters": 236.5882365,
                        "name": name,
                        "qualifier": qualifier,
                        "allowStandard": allow,
                        "expect": grams_for(236.5882365, name, qualifier, allow_standard=allow),
                    }
                    for name in DENSITY_NAMES
                    for qualifier in ("", "sifted")
                    for allow in (True, False)
                ],
            },
        )

    def test_food_data_cases(self):
        searches = []
        for response in SEARCH_RESPONSES:
            with mock.patch.object(food_data, "_request", return_value={"foods": response["foods"]}):
                matches = food_data.search_foods(response["query"], scope=response["scope"])
            searches.append({**response, "expect": [match.as_json() for match in matches]})
        details = []
        for payload in DETAILS:
            with mock.patch.object(food_data, "_request", return_value=payload):
                result = _or_error(food_data.get_food, 1)
            details.append(
                {
                    "payload": payload,
                    "expect": result
                    if isinstance(result, dict)
                    else {
                        "description": result[0],
                        "per100g": result[1],
                        "packageIngredients": result[2],
                    },
                }
            )
        pin(
            self,
            "food-data-cases.json",
            {
                "nutritionPer100g": [
                    {"payload": food, "expect": _or_error(food_data.nutrition_per_100g, food)}
                    for food in FOODS
                ],
                "ranked": [
                    {
                        **ranking,
                        "expect": [
                            match.fdc_id
                            for match in food_data._ranked(
                                ranking["query"],
                                [
                                    food_data.FoodDataMatch(
                                        entry["fdcId"],
                                        entry["description"],
                                        entry["dataType"],
                                        entry["brand"],
                                    )
                                    for entry in ranking["matches"]
                                ],
                            )
                        ],
                    }
                    for ranking in RANKINGS
                ],
                "search": searches,
                "details": details,
                "labelNutritionPer100g": [
                    {
                        **label,
                        "expect": _or_error(
                            food_data.label_nutrition_per_100g,
                            label["values"],
                            label["servingGrams"],
                        ),
                    }
                    for label in LABELS
                ],
            },
        )

